import csv, re, html, math, collections, statistics
from pathlib import Path

DATA = Path('/app/benchmark/data.csv')
OUT = Path('/app/output/final_report.html')
OUT.parent.mkdir(parents=True, exist_ok=True)

with DATA.open(newline='', encoding='utf-8') as f:
    rows = list(csv.DictReader(f))

present_years = sorted({int(r['year']) for r in rows})
full_years = list(range(2015, 2026))
missing_years = [y for y in full_years if y not in present_years]
types = ['MCQs', 'Short', 'Long']
colors = {'MCQs': '#2563eb', 'Short': '#14b8a6', 'Long': '#f97316'}
light_colors = {'MCQs': '#dbeafe', 'Short': '#ccfbf1', 'Long': '#ffedd5'}

by_year = {y: collections.Counter(r['type'] for r in rows if int(r['year']) == y) for y in present_years}
year_totals = {y: sum(by_year[y].values()) for y in present_years}
overall_type = collections.Counter(r['type'] for r in rows)

yoy = []
prev_year = None
prev_total = None
for y in present_years:
    total = year_totals[y]
    if prev_total is None:
        yoy.append((y, total, None, None))
    else:
        diff = total - prev_total
        pct = (diff / prev_total * 100) if prev_total else None
        yoy.append((y, total, diff, pct))
    prev_year, prev_total = y, total

avg_per_type = {t: sum(by_year[y][t] for y in present_years) / len(present_years) for t in types}
minmax_type = {t: (min(by_year[y][t] for y in present_years), max(by_year[y][t] for y in present_years)) for t in types}
shares_overall = {t: overall_type[t] / len(rows) * 100 for t in types}

# Text processing. Keep method simple and explicit: keyword counts after punctuation/$ cleanup.
stop = set('''a an and are as at be been being by called can class compare define describe do does each else explain for from function give has have how if in into is it list name of on or over program purpose show state statement statements structure the their this to use used using what when which while with write you your following also between any within its why example examples type types different two three one number numbers output input difference advantages disadvantages explain syntax purpose describe define show method methods part parts option options true false paper question questions'''.split())
romans = set('i ii iii iv v vi vii viii ix x xi xii xiii xiv xv'.split())
synonyms = {
    'arrays': 'array', 'functions': 'function', 'loops': 'loop', 'databases': 'database',
    'records': 'record', 'fields': 'field', 'pointers': 'pointer', 'operators': 'operator',
    'flow': 'flowchart', 'chart': 'flowchart', 'flowcharts': 'flowchart', 'algorithms': 'algorithm',
    'structures': 'structure', 'variables': 'variable', 'objects': 'object', 'files': 'file',
    'tables': 'table', 'relations': 'relation', 'attributes': 'attribute', 'queries': 'query',
    'keys': 'key'
}
words = []
words_by_type = {t: [] for t in types}
for r in rows:
    text = r['question'].replace('$', ' ')
    for tok in re.findall(r"[A-Za-z][A-Za-z+]*", text.lower()):
        tok = synonyms.get(tok, tok)
        if len(tok) < 2 or tok in stop or tok in romans:
            continue
        words.append(tok)
        words_by_type[r['type']].append(tok)
word_counts = collections.Counter(words)
top_words = word_counts.most_common(18)

def norm_tokens(text):
    return {synonyms.get(tok, tok) for tok in re.findall(r"[A-Za-z][A-Za-z+]*", text.replace('$', ' ').lower())}

topic_categories = {
    'C programming control & syntax': ['loop', 'while', 'switch', 'case', 'statement', 'operator', 'function', 'array', 'pointer', 'variable', 'int', 'char', 'break', 'continue', 'printf', 'scanf', 'constructor', 'destructor'],
    'Database concepts': ['database', 'record', 'field', 'file', 'table', 'key', 'primary', 'foreign', 'attribute', 'entity', 'relation', 'relational', 'query', 'sql', 'normalization', 'index'],
    'Algorithms, flowcharts & data structures': ['flowchart', 'algorithm', 'stack', 'queue', 'tree', 'binary', 'search', 'sorting', 'pseudocode', 'process', 'symbol'],
    'Object-oriented programming': ['oop', 'object', 'class', 'inheritance', 'polymorphism', 'encapsulation', 'constructor', 'destructor', 'oriented'],
    'Computer systems & networking': ['network', 'internet', 'protocol', 'software', 'hardware', 'memory', 'computer', 'input', 'output', 'operating', 'system'],
}
category_totals = {cat: 0 for cat in topic_categories}
category_year = {cat: {y: 0 for y in present_years} for cat in topic_categories}
category_type = {cat: {t: 0 for t in types} for cat in topic_categories}
for r in rows:
    toks = norm_tokens(r['question'])
    y = int(r['year'])
    for cat, keys in topic_categories.items():
        if toks.intersection(keys):
            category_totals[cat] += 1
            category_year[cat][y] += 1
            category_type[cat][r['type']] += 1

phrase_patterns = {
    'database management / DBMS': r'\bdatabase\s+management\b|\bdbms\b',
    'primary key': r'\bprimary\s+key\b',
    'foreign key': r'\bforeign\s+key\b',
    'while loop': r'\bwhile\s+loop\b',
    'for loop': r'\bfor\s+loop\b',
    'switch statement': r'\bswitch\s+statement\b',
    'format specifier': r'\bformat\s+specifier\b',
    'data type': r'\bdata\s+type\b',
    'MS Access': r'\bms\s+access\b',
    'do-while loop': r'\bdo[-\s]+while\s+loop\b',
    'control structure': r'\bcontrol\s+structure\b',
    'object oriented / OOP': r'\bobject[-\s]+oriented\b|\boop\b',
}
phrase_counts = []
for label, pat in phrase_patterns.items():
    count = sum(len(re.findall(pat, r['question'].replace('$', ' ').lower())) for r in rows)
    phrase_counts.append((label, count))
phrase_counts.sort(key=lambda x: (-x[1], x[0].lower()))

# SVG helpers

def svg_line_chart(data, width=920, height=330):
    margin = {'l': 58, 'r': 24, 't': 28, 'b': 46}
    xs = [y for y, _ in data]
    vals = [v for _, v in data]
    min_v = 0
    max_v = max(vals) + 4
    plot_w = width - margin['l'] - margin['r']
    plot_h = height - margin['t'] - margin['b']
    def x_pos(i): return margin['l'] + (plot_w * i / (len(data)-1 if len(data)>1 else 1))
    def y_pos(v): return margin['t'] + plot_h - ((v - min_v) / (max_v - min_v) * plot_h)
    y_ticks = [0, 10, 20, 30, 40]
    parts = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Total questions per year line chart">']
    parts.append('<rect width="100%" height="100%" fill="#ffffff"/>')
    for tick in y_ticks:
        y = y_pos(tick)
        parts.append(f'<line x1="{margin["l"]}" y1="{y:.1f}" x2="{width-margin["r"]}" y2="{y:.1f}" stroke="#e5e7eb"/>')
        parts.append(f'<text x="{margin["l"]-10}" y="{y+4:.1f}" text-anchor="end" font-size="12" fill="#64748b">{tick}</text>')
    points = [(x_pos(i), y_pos(v)) for i, (yr, v) in enumerate(data)]
    path = ' '.join(('M' if i == 0 else 'L') + f' {x:.1f} {y:.1f}' for i, (x, y) in enumerate(points))
    parts.append(f'<path d="{path}" fill="none" stroke="#1d4ed8" stroke-width="3"/>')
    for i, ((yr, v), (x, y)) in enumerate(zip(data, points)):
        parts.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="5" fill="#1d4ed8"/>')
        parts.append(f'<text x="{x:.1f}" y="{y-10:.1f}" text-anchor="middle" font-size="12" font-weight="700" fill="#0f172a">{v}</text>')
        parts.append(f'<text x="{x:.1f}" y="{height-17}" text-anchor="middle" font-size="12" fill="#475569">{yr}</text>')
    parts.append(f'<text x="18" y="{height/2}" transform="rotate(-90 18 {height/2})" text-anchor="middle" font-size="12" fill="#475569">Question count</text>')
    parts.append('</svg>')
    return ''.join(parts)


def svg_stacked_bars(years, width=920, height=380, percent=False):
    margin = {'l': 58, 'r': 24, 't': 30, 'b': 58}
    plot_w = width - margin['l'] - margin['r']
    plot_h = height - margin['t'] - margin['b']
    max_v = 100 if percent else max(year_totals.values()) + 3
    bar_gap = 18
    bar_w = (plot_w - bar_gap * (len(years)-1)) / len(years)
    parts = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Stacked bar chart by question type">']
    parts.append('<rect width="100%" height="100%" fill="#ffffff"/>')
    ticks = [0, 25, 50, 75, 100] if percent else [0, 10, 20, 30, 40]
    for tick in ticks:
        y = margin['t'] + plot_h - (tick / max_v * plot_h)
        parts.append(f'<line x1="{margin["l"]}" y1="{y:.1f}" x2="{width-margin["r"]}" y2="{y:.1f}" stroke="#e5e7eb"/>')
        label = f'{tick}%' if percent else str(tick)
        parts.append(f'<text x="{margin["l"]-10}" y="{y+4:.1f}" text-anchor="end" font-size="12" fill="#64748b">{label}</text>')
    for i, yval in enumerate(years):
        x = margin['l'] + i * (bar_w + bar_gap)
        base = margin['t'] + plot_h
        total = year_totals[yval]
        for t in types:
            raw = by_year[yval][t]
            value = raw / total * 100 if percent else raw
            h = value / max_v * plot_h
            base -= h
            parts.append(f'<rect x="{x:.1f}" y="{base:.1f}" width="{bar_w:.1f}" height="{h:.1f}" fill="{colors[t]}" rx="3"/>')
            if h > 18:
                label = f'{raw}' if not percent else f'{raw/total*100:.0f}%'
                parts.append(f'<text x="{x+bar_w/2:.1f}" y="{base+h/2+4:.1f}" text-anchor="middle" font-size="11" font-weight="700" fill="#fff">{label}</text>')
        parts.append(f'<text x="{x+bar_w/2:.1f}" y="{height-26}" text-anchor="middle" font-size="12" fill="#475569">{yval}</text>')
        if not percent:
            parts.append(f'<text x="{x+bar_w/2:.1f}" y="{margin["t"]-9}" text-anchor="middle" font-size="12" font-weight="700" fill="#0f172a">{total}</text>')
    lx = margin['l']
    for j, t in enumerate(types):
        parts.append(f'<rect x="{lx + j*105}" y="{height-14}" width="12" height="12" fill="{colors[t]}" rx="2"/>')
        parts.append(f'<text x="{lx + j*105 + 18}" y="{height-4}" font-size="12" fill="#475569">{t}</text>')
    parts.append('</svg>')
    return ''.join(parts)


def svg_horizontal_bars(items, width=920, height=520, label_width=170, color='#2563eb'):
    margin = {'l': label_width, 'r': 42, 't': 22, 'b': 24}
    plot_w = width - margin['l'] - margin['r']
    row_h = (height - margin['t'] - margin['b']) / len(items)
    max_v = max(v for _, v in items)
    parts = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Horizontal keyword frequency bar chart">']
    parts.append('<rect width="100%" height="100%" fill="#ffffff"/>')
    for i, (label, val) in enumerate(items):
        y = margin['t'] + i * row_h
        bar_h = max(10, row_h * 0.62)
        w = val / max_v * plot_w
        parts.append(f'<text x="{margin["l"]-12}" y="{y+bar_h/2+4:.1f}" text-anchor="end" font-size="13" fill="#334155">{html.escape(label)}</text>')
        parts.append(f'<rect x="{margin["l"]}" y="{y:.1f}" width="{w:.1f}" height="{bar_h:.1f}" fill="{color}" rx="5"/>')
        parts.append(f'<text x="{margin["l"]+w+8:.1f}" y="{y+bar_h/2+4:.1f}" font-size="12" font-weight="700" fill="#0f172a">{val}</text>')
    parts.append('</svg>')
    return ''.join(parts)


def svg_topic_heatmap(width=920, height=350):
    cats = list(topic_categories.keys())
    margin = {'l': 235, 'r': 30, 't': 34, 'b': 36}
    cell_w = (width - margin['l'] - margin['r']) / len(present_years)
    cell_h = (height - margin['t'] - margin['b']) / len(cats)
    max_v = max(category_year[c][y] for c in cats for y in present_years)
    def shade(v):
        if v == 0: return '#f8fafc'
        alpha = 0.18 + 0.72 * v / max_v
        # interpolate from light teal to dark blue
        r1,g1,b1 = (204,251,241); r2,g2,b2=(15,118,110)
        r=round(r1+(r2-r1)*alpha); g=round(g1+(g2-g1)*alpha); b=round(b1+(b2-b1)*alpha)
        return f'rgb({r},{g},{b})'
    parts = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Topic category heatmap by year">']
    parts.append('<rect width="100%" height="100%" fill="#ffffff"/>')
    for j, y in enumerate(present_years):
        x = margin['l'] + j * cell_w + cell_w/2
        parts.append(f'<text x="{x:.1f}" y="20" text-anchor="middle" font-size="12" fill="#475569">{y}</text>')
    for i, cat in enumerate(cats):
        y0 = margin['t'] + i * cell_h
        parts.append(f'<text x="{margin["l"]-12}" y="{y0+cell_h/2+4:.1f}" text-anchor="end" font-size="12" fill="#334155">{html.escape(cat)}</text>')
        for j, yr in enumerate(present_years):
            x0 = margin['l'] + j * cell_w
            v = category_year[cat][yr]
            fill = shade(v)
            txt = '#ffffff' if v >= 10 else '#0f172a'
            parts.append(f'<rect x="{x0+2:.1f}" y="{y0+2:.1f}" width="{cell_w-4:.1f}" height="{cell_h-4:.1f}" fill="{fill}" rx="5"/>')
            parts.append(f'<text x="{x0+cell_w/2:.1f}" y="{y0+cell_h/2+4:.1f}" text-anchor="middle" font-size="12" font-weight="700" fill="{txt}">{v}</text>')
    parts.append('<text x="235" y="340" font-size="11" fill="#64748b">Cells count questions containing at least one keyword from the topic group; categories can overlap.</text>')
    parts.append('</svg>')
