        yoy.append((y, total, diff, pct))
    prev_year, prev_total = y, total

avg_per_type = {t: sum(by_year[y][t] for y in present_years) / len(present_years) for t in types}
minmax_type = {t: (min(by_year[y][t] for y in present_years), max(by_year[y][t] for y in present_years)) for t in types}
shares_overall = {t: overall_type[t] / len(rows) * 100 for t in types}

# Text processing. Keep method simple and explicit: keyword counts after punctuation/$ cleanup.
stop = set('''a an and are as at be been being by called can class compare define describe do does each else explain for from function give has have how if in into is it list name of on or over program purpose show state statement statements structure the their this to use used using what when which while with write you your following also between any within its why example examples type types different two three one number numbers output input difference advantages disadvantages explain syntax purpose describe define show method methods part parts option options true false paper question questions'''.split())
romans = set('i ii iii iv v vi vii viii ix x xi xii xiii xiv xv'.split())
synonyms = {
    'arrays': 'array', 'functions': 'function', 'loops': 'loop', 'databases': 'database',
    'records': 'record', 'fields': 'field', 'pointers': 'pointer', 'operators': 'operator',
    'flow': 'flowchart', 'chart': 'flowchart', 'flowcharts': 'flowchart', 'algorithms': 'algorithm',
    'structures': 'structure', 'variables': 'variable', 'objects': 'object', 'files': 'file',
    'tables': 'table', 'relations': 'relation', 'attributes': 'attribute', 'queries': 'query',
    'keys': 'key'
}
words = []
words_by_type = {t: [] for t in types}
for r in rows:
    text = r['question'].replace('$', ' ')
    for tok in re.findall(r"[A-Za-z][A-Za-z+]*", text.lower()):
        tok = synonyms.get(tok, tok)
        if len(tok) < 2 or tok in stop or tok in romans:
            continue
        words.append(tok)
        words_by_type[r['type']].append(tok)
word_counts = collections.Counter(words)
top_words = word_counts.most_common(18)

def norm_tokens(text):
    return {synonyms.get(tok, tok) for tok in re.findall(r"[A-Za-z][A-Za-z+]*", text.replace('$', ' ').lower())}

topic_categories = {
    'C programming control & syntax': ['loop', 'while', 'switch', 'case', 'statement', 'operator', 'function', 'array', 'pointer', 'variable', 'int', 'char', 'break', 'continue', 'printf', 'scanf', 'constructor', 'destructor'],
    'Database concepts': ['database', 'record', 'field', 'file', 'table', 'key', 'primary', 'foreign', 'attribute', 'entity', 'relation', 'relational', 'query', 'sql', 'normalization', 'index'],
    'Algorithms, flowcharts & data structures': ['flowchart', 'algorithm', 'stack', 'queue', 'tree', 'binary', 'search', 'sorting', 'pseudocode', 'process', 'symbol'],
    'Object-oriented programming': ['oop', 'object', 'class', 'inheritance', 'polymorphism', 'encapsulation', 'constructor', 'destructor', 'oriented'],
    'Computer systems & networking': ['network', 'internet', 'protocol', 'software', 'hardware', 'memory', 'computer', 'input', 'output', 'operating', 'system'],
}
category_totals = {cat: 0 for cat in topic_categories}
category_year = {cat: {y: 0 for y in present_years} for cat in topic_categories}
category_type = {cat: {t: 0 for t in types} for cat in topic_categories}
for r in rows:
    toks = norm_tokens(r['question'])
    y = int(r['year'])
    for cat, keys in topic_categories.items():
        if toks.intersection(keys):
            category_totals[cat] += 1
            category_year[cat][y] += 1
            category_type[cat][r['type']] += 1

phrase_patterns = {
    'database management / DBMS': r'\bdatabase\s+management\b|\bdbms\b',
    'primary key': r'\bprimary\s+key\b',
    'foreign key': r'\bforeign\s+key\b',
