        r=round(r1+(r2-r1)*alpha); g=round(g1+(g2-g1)*alpha); b=round(b1+(b2-b1)*alpha)
        return f'rgb({r},{g},{b})'
    parts = [f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Topic category heatmap by year">']
    parts.append('<rect width="100%" height="100%" fill="#ffffff"/>')
    for j, y in enumerate(present_years):
        x = margin['l'] + j * cell_w + cell_w/2
        parts.append(f'<text x="{x:.1f}" y="20" text-anchor="middle" font-size="12" fill="#475569">{y}</text>')
    for i, cat in enumerate(cats):
        y0 = margin['t'] + i * cell_h
        parts.append(f'<text x="{margin["l"]-12}" y="{y0+cell_h/2+4:.1f}" text-anchor="end" font-size="12" fill="#334155">{html.escape(cat)}</text>')
        for j, yr in enumerate(present_years):
            x0 = margin['l'] + j * cell_w
